// Payload esperado: { contact_id, motivo: 'email_reply'|'whatsapp_reply'|'cita', nombre?, empresa?, cuello?, puntos?, texto_respuesta? }
// Lo llaman: el workflow de GHL de Landing (reply de email / cita creada) y los workflows del agente
// de WhatsApp de Outbound (reply de WhatsApp). Idempotente: repetir la llamada no duplica daño.
const entrada = $input.first().json;
const b = entrada.body || entrada;
if (!b.contact_id) throw new Error('Payload sin contact_id.');

const quitarAcentos = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const cuello = quitarAcentos(b.cuello || 'ninguno');
const motivo = ['email_reply', 'whatsapp_reply', 'cita'].includes(b.motivo) ? b.motivo : 'email_reply';

const REACCION = {
  captacion: 'Reacciona con su número: cuántas oportunidades son al año y qué valen con su ticket medio. Una frase, sin adjetivos.',
  conversion: 'Reacciona con su número: minutos u horas de espera → cuántos leads se enfrían al mes con su volumen. Una frase, sin adjetivos.',
  seguimiento: "Ejemplo del guion: 'Ocho presupuestos sin respuesta. Si tu ticket medio anda por los 2.000 €, son 16.000 € que ya te costaron atraer y calcular, esperando una llamada de dos minutos.'",
  dependencia: 'Reacciona con su número: cuántas de 30 se atenderían sin él → % del negocio que depende de su agenda. Una frase, sin adjetivos.',
  control: 'Reacciona con su número (o su “no lo sé”): no saber de dónde salió el último cliente es la fuga misma. Una frase, sin adjetivos.',
  ninguno: 'Reacciona a la pieza que nombró: qué costaría al año que se cayera. Una frase, sin adjetivos.',
};

const PUENTE = 'Con ese dato y tu ticket medio te lo pongo en un folio: cuánto se está escapando y qué haría yo primero. ¿Lo vemos en 20 minutos con tus números delante, o te lo mando por escrito?';
const NI_IDEA = "Si dice 'ni idea': 'Es lo normal, casi nadie lo tiene. Justo por eso: ¿lo miramos en 20 minutos o prefieres que te mande cómo contarlo en una semana?'";

const quien = [b.nombre, b.empresa].filter(Boolean).join(' · ') || b.contact_id;
const nota = `[secuencia radiografía] PARADA por ${motivo}. ${b.texto_respuesta ? 'Respuesta literal: «' + b.texto_respuesta + '»' : 'Sin texto adjunto.'}`;

const tareaTitulo = `PUENTE (responder <2h) · ${quien}`;
const tareaCuerpo =
  `Contestó a la secuencia de la radiografía (${motivo}). Secuencia parada.\n\n` +
  `Mini-brief: cuello ${cuello}${b.puntos ? ' · ' + b.puntos + '/100' : ''}${b.empresa ? ' · ' + b.empresa : ''}.\n` +
  `${b.texto_respuesta ? 'Qué dijo: «' + b.texto_respuesta + '»\n' : ''}` +
  `\n1) ${REACCION[cuello] || REACCION.ninguno}\n` +
  `2) Puente (dos salidas, las dos avanzan):\n«${PUENTE}»\n` +
  `- 20 min → agenda con huecos reales.\n- Por escrito → tarea a Ventas “plan 48 h” con el brief.\n${NI_IDEA}`;

return [{ json: { contact_id: b.contact_id, motivo, esCita: motivo === 'cita', nota, tareaTitulo, tareaCuerpo } }];
